/* eslint-disable @next/next/no-img-element -- tiny static brand files, already sized: no optimisation needed */

/**
 * Official Italian Rainforest logo (public/brand, generated by scripts/prepare-brand.mjs).
 *  - white: the default — header, hero and every dark or coloured background;
 *  - blue:  white backgrounds and the footer.
 * Legacy tone names are kept: "light" = white artwork, "dark" = blue artwork.
 */
type Tone = 'white' | 'blue' | 'light' | 'dark';
const file = (tone: Tone) => (tone === 'blue' || tone === 'dark' ? 'blue' : 'white');
const RATIO = 826 / 240; // lockup width / height

/** Canopy outline of the umbrella-tree, reused for the small map markers in the illustrations. */
export const MARK_CANOPY = 'M61 108A139 118 0 0 0 339 108a34.5 21 0 0 1-69 0 35 21 0 0 1-70 0 35 21 0 0 1-70 0 34.5 21 0 0 1-69 0Z';

/** Circle mark only (embeds, favicon-sized places). */
export function LogoMark({ size = 36, tone = 'blue', className }: { size?: number; tone?: Tone | 'brand' | 'outline'; className?: string }) {
  const t: Tone = tone === 'outline' ? 'white' : tone === 'brand' ? 'blue' : tone;
  return <img src={`/brand/irf-mark-${file(t)}.png`} width={size} height={size} alt="" aria-hidden="true" className={className} />;
}

/** Full lockup: mark + "Italian Rainforest". `size` is the height in px. */
export function Logo({ tone = 'white', size = 36, className = '' }: { tone?: Tone; size?: number; className?: string }) {
  return (
    <img
      src={`/brand/irf-logo-${file(tone)}.webp`}
      width={Math.round(size * RATIO)}
      height={size}
      alt="Italian Rainforest"
      className={`block h-auto max-w-full ${className}`}
      style={{ height: size, width: 'auto' }}
    />
  );
}
